UNITS = [{'id': 'PEDS-U185', 'ch': 23, 'n': 1, 'title': 'Diarrheal Disorders — Types (Acute / Persistent / Chronic)', 'sec': 'Diarrheal Disorders in Children · p99', 'qs': ['PEDS-C23-001', 'PEDS-C23-002', 'PEDS-C23-003', 'PEDS-C23-004', 'PEDS-C23-005', 'PEDS-C23-006', 'PEDS-C23-007'], 'guide': 'Diarrheal disorders are major contributors of under-5 mortality. Types: Acute — < 7 days, infections. Persistent — > 14 days, prolonged infection. Chronic — > 14 days (upto months), non-infectious causes (especially malabsorption).'}, {'id': 'PEDS-U186', 'ch': 23, 'n': 2, 'title': 'Acute Diarrhea — Etiology & Dysentery', 'sec': 'Acute Diarrhea · p99', 'qs': ['PEDS-C23-008', 'PEDS-C23-009', 'PEDS-C23-010', 'PEDS-C23-011', 'PEDS-C23-012', 'PEDS-C23-013', 'PEDS-C23-014', 'PEDS-C23-015'], 'guide': 'Acute diarrhea: m/c cause — Rotavirus; other viral — Norwalk, adeno, astro & calicivirus; m/c bacteria — ETEC (enterotoxigenic E. coli). Dysentery = diarrhea + blood in stool; m/c cause — Shigella flexneri.'}, {'id': 'PEDS-U187', 'ch': 23, 'n': 3, 'title': 'Dehydration — Assessment (Look, Feel, Decide & Treat)', 'sec': 'Dehydration · p99', 'qs': ['PEDS-C23-016', 'PEDS-C23-017', 'PEDS-C23-018', 'PEDS-C23-019', 'PEDS-C23-020', 'PEDS-C23-021', 'PEDS-C23-022', 'PEDS-C23-023', 'PEDS-C23-024', 'PEDS-C23-025', 'PEDS-C23-026', 'PEDS-C23-027', 'PEDS-C23-028', 'PEDS-C23-029'], 'guide': 'Dehydration is the primary concern in diarrhea — look, feel, decide & treat. No dehydration — active & alert, normal eyes/tears/mouth/thirst, pinch fast (< 1 sec). Some — irritable, sunken eyes, absent tears, dry mouth, severe thirst, pinch slow (< 2 sec). Severe — lethargy (cannot be aroused), very sunken eyes, very dry mouth, unable to drink, pinch very slow (> 2 sec). Skin pinch tests turgor/elasticity which depends on interstitial fluid.'}, {'id': 'PEDS-U188', 'ch': 23, 'n': 4, 'title': 'Plan A — No Dehydration (Low Osmolarity ORS)', 'sec': 'Management — Plan A · p100', 'qs': ['PEDS-C23-030', 'PEDS-C23-031', 'PEDS-C23-032', 'PEDS-C23-033', 'PEDS-C23-034', 'PEDS-C23-035', 'PEDS-C23-036', 'PEDS-C23-037', 'PEDS-C23-038', 'PEDS-C23-039', 'PEDS-C23-040', 'PEDS-C23-041'], 'guide': 'Plan A: low osmolarity ORS — glucose 75, Na 75, K 20, Cl 65, citrate 10; total 245 mosm/L; glucose:Na 1:1 for maximum absorption via SGLT-1. Home alternatives: salted rice water, salted yogurt, soup with salt, fresh fruit juice (no sugar), tender coconut water — avoid packed juices (added sugar). Amount of ORS (replace ongoing losses): < 2 yr 50–100 mL/stool; 2–10 yr 100–200 mL; > 10 yr ad lib.'}, {'id': 'PEDS-U189', 'ch': 23, 'n': 5, 'title': 'Plan B — Some Dehydration (75 mL/kg over 4 hrs)', 'sec': 'Plan B · p100', 'qs': ['PEDS-C23-042', 'PEDS-C23-043', 'PEDS-C23-044', 'PEDS-C23-045', 'PEDS-C23-046', 'PEDS-C23-047', 'PEDS-C23-048', 'PEDS-C23-049', 'PEDS-C23-050'], 'guide': 'Plan B: ORS corrects dehydration — 1. Rehydration: 75 mL/kg ORS over 4 hrs. 2. Replacement of ongoing loss: same as Plan A. 3. Maintenance (Holliday–Segar): first 10 kg — 100 mL/kg; 10–20 kg — 1000 mL + 50 mL/kg after 10 kg; > 20 kg — 1500 mL + 20 mL/kg after 20 kg.'}, {'id': 'PEDS-U190', 'ch': 23, 'n': 6, 'title': 'Plan C — Severe Dehydration (IV RL + 5% Dextrose) & Zinc', 'sec': 'Plan C · p100', 'qs': ['PEDS-C23-051', 'PEDS-C23-052', 'PEDS-C23-053', 'PEDS-C23-054', 'PEDS-C23-055', 'PEDS-C23-056', 'PEDS-C23-057', 'PEDS-C23-058', 'PEDS-C23-059', 'PEDS-C23-060', 'PEDS-C23-061', 'PEDS-C23-062', 'PEDS-C23-063'], 'guide': 'Plan C: IV fluids RL + 5% dextrose; rehydration 100 mL/kg. < 1 yr: 30 mL/kg over 1 hr + 70 mL/kg over 5 hrs = 6 hrs. > 1 yr: 30 mL/kg over 30 min + 70 mL/kg over 2.5 hrs = 3 hrs. Zinc for 14 days — GI re-epithelialisation, ↓ risk of persistent diarrhea; dose: < 6 months 10 mg/day, > 6 months 20 mg/day.'}, {'id': 'PEDS-U191', 'ch': 23, 'n': 7, 'title': 'Additional Drugs & Convulsions with Diarrhea', 'sec': 'Additional drugs · p101', 'qs': ['PEDS-C23-064', 'PEDS-C23-065', 'PEDS-C23-066', 'PEDS-C23-067', 'PEDS-C23-068', 'PEDS-C23-069', 'PEDS-C23-070', 'PEDS-C23-071', 'PEDS-C23-072', 'PEDS-C23-073'], 'guide': 'Additional drugs: dysentery — 3rd generation cephalosporin; vomiting — ondansetron 0.15 mg/kg/dose orally; probiotics (cost-benefit) — Lactobacillus rhamnosus & Saccharomyces boulardii. Convulsions with diarrhea: electrolyte/metabolic (hypo/hypernatremia, hypoglycemia), infections (febrile seizures, meningitis/encephalitis), dehydration → cerebral venous & sagittal sinus thrombosis.'}, {'id': 'PEDS-U192', 'ch': 23, 'n': 8, 'title': 'Persistent Diarrhea — Risk Factors & Management (Vitamin A, Lactose, Diet Ladder)', 'sec': 'Persistent Diarrhea · p101', 'qs': ['PEDS-C23-074', 'PEDS-C23-075', 'PEDS-C23-076', 'PEDS-C23-077', 'PEDS-C23-078', 'PEDS-C23-079', 'PEDS-C23-080', 'PEDS-C23-081', 'PEDS-C23-082', 'PEDS-C23-083', 'PEDS-C23-084', 'PEDS-C23-085', 'PEDS-C23-086', 'PEDS-C23-087'], 'guide': 'Risk factors: malnutrition (↓ immunity), immunodeficiency. Management: ORS/IV fluids per dehydration; zinc; vitamin A single dose (< 8 kg 1 lakh IU, > 8 kg 2 lakh IU); lactose restriction — milk < 50 mL/kg/day. Persistent diarrhea → villi damage → ↓ lactase → lactose intolerance → unabsorbed lactose + colonic bacteria → H2 (gaseous stool) & lactic acid (↓ pH, perianal excoriation). Diet ladder: no-lactose diet (↓ sugars & starch; plain glucose, cereals, egg white, chicken) → no response → no lactose, no starch — only egg yolk/chicken (protein).'}, {'id': 'PEDS-U193', 'ch': 23, 'n': 9, 'title': 'Celiac Disease — Gluten, Pathogenesis, Diagnosis & Treatment', 'sec': 'Celiac Disease · p102', 'qs': ['PEDS-C23-088', 'PEDS-C23-089', 'PEDS-C23-090', 'PEDS-C23-091', 'PEDS-C23-092', 'PEDS-C23-093', 'PEDS-C23-094', 'PEDS-C23-095', 'PEDS-C23-096', 'PEDS-C23-097', 'PEDS-C23-098', 'PEDS-C23-099', 'PEDS-C23-100', 'PEDS-C23-101', 'PEDS-C23-102', 'PEDS-C23-103', 'PEDS-C23-104'], 'guide': 'Celiac disease: gluten hypersensitivity causing chronic diarrhea. Gluten foods (BROW): barley, rye, oats (relatively well tolerated), wheat (m/c implicated). HLA DQ2 & DQ8; T cell mediated autoimmune disorder: genetic predisposition + gluten → gliadin (intestinal absorption) → T cell → B cell → autoantibodies → intestinal injury. Associations: Down, Turner, Hashimoto, selective IgA deficiency, T1DM. Onset ≥ 6 months (after stoppage of exclusive breastfeeding). Anemia: iron (duodenum) + folate (terminal ileum) → dimorphic, iron-refractory. Diagnosis: anti-tTG (screening), anti-endomysial (best); duodenal biopsy — IOC in India (villous atrophy, ↑ crypt length, ↑ IEL > 30/100 enterocytes). Treatment: lifelong gluten-free diet (substitute rice & maize).'}]

